-- ----------------------------
-- Table structure for sys_algorithm
-- ----------------------------
DROP TABLE IF EXISTS `sys_algorithm`;
CREATE TABLE `sys_algorithm`  (
  `algorithm_id` bigint NOT NULL AUTO_INCREMENT COMMENT '算法ID',
  `algorithm_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '算法名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '算法描述',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否启用',
  `algorithm_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '算法类型(data_cleaning,backdoor_detection,model_purification等)',
  `defense_stage` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '防御阶段(pre,during,post)',
  `algorithm_category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '算法分类(statistical,ml_based,deep_learning等)',
  `implementation_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '算法实现文件路径',
  `default_config` json NULL COMMENT '默认配置(JSON格式)',
  `config_schema` json NULL COMMENT '配置参数模式(JSON格式)',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`algorithm_id`) USING BTREE,
  UNIQUE INDEX `uniq_algorithm_name`(`algorithm_name` ASC) USING BTREE,
  INDEX `idx_algorithm_type`(`algorithm_type` ASC) USING BTREE,
  INDEX `idx_defense_stage`(`defense_stage` ASC) USING BTREE,
  INDEX `idx_enabled`(`enabled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '算法表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of sys_algorithm
-- ----------------------------
INSERT INTO `sys_algorithm` VALUES (1, '统计异常检测', '基于统计方法检测异常样本，适用于数据预处理阶段', b'1', 'data_cleaning', 'pre', 'statistical', '/algorithms/statistical_outlier_detection.py', '{\"method\": \"zscore\", \"threshold\": 2.0, \"contamination\": 0.1}', '{\"method\": {\"type\": \"select\", \"default\": \"zscore\", \"options\": [\"zscore\", \"iqr\", \"isolation\"], \"description\": \"检测方法\"}, \"threshold\": {\"max\": 5.0, \"min\": 1.0, \"type\": \"float\", \"default\": 2.0, \"description\": \"阈值\"}, \"contamination\": {\"max\": 0.5, \"min\": 0.01, \"type\": \"float\", \"default\": 0.1, \"description\": \"污染比例\"}}', 'admin', 'admin', '2025-07-28 09:00:00', '2025-07-28 09:00:00');
INSERT INTO `sys_algorithm` VALUES (2, 'STRIP后门检测', 'STRIP算法用于检测训练中的后门攻击', b'1', 'backdoor_detection', 'during', 'deep_learning', '/algorithms/strip_detection.py', '{\"batch_size\": 32, \"perturbation_ratio\": 0.1, \"detection_threshold\": 0.5}', '{\"batch_size\": {\"max\": 128, \"min\": 16, \"type\": \"int\", \"default\": 32, \"description\": \"批次大小\"}, \"perturbation_ratio\": {\"max\": 0.5, \"min\": 0.01, \"type\": \"float\", \"default\": 0.1, \"description\": \"扰动比例\"}, \"detection_threshold\": {\"max\": 0.9, \"min\": 0.1, \"type\": \"float\", \"default\": 0.5, \"description\": \"检测阈值\"}}', 'admin', 'admin', '2025-07-28 09:30:00', '2025-07-28 09:30:00');
INSERT INTO `sys_algorithm` VALUES (3, '神经元修剪', '通过修剪可疑神经元来净化被后门攻击的模型', b'1', 'model_purification', 'post', 'deep_learning', '/algorithms/neural_cleanse.py', '{\"learning_rate\": 0.001, \"pruning_ratio\": 0.05, \"fine_tune_epochs\": 10}', '{\"learning_rate\": {\"max\": 0.01, \"min\": 0.0001, \"type\": \"float\", \"default\": 0.001, \"description\": \"学习率\"}, \"pruning_ratio\": {\"max\": 0.2, \"min\": 0.01, \"type\": \"float\", \"default\": 0.05, \"description\": \"修剪比例\"}, \"fine_tune_epochs\": {\"max\": 50, \"min\": 1, \"type\": \"int\", \"default\": 10, \"description\": \"微调轮数\"}}', 'admin', 'admin', '2025-07-28 10:00:00', '2025-07-28 10:00:00');
INSERT INTO `sys_algorithm` VALUES (4, 'ABL防御算法', 'Anti-Backdoor Learning，适用于训练中防御', b'1', 'backdoor_detection', 'during', 'ml_based', '/algorithms/abl_defense.py', '{\"isolation_ratio\": 0.02, \"unlearning_epochs\": 5, \"gradient_ascent_step\": 0.1}', '{\"isolation_ratio\": {\"max\": 0.1, \"min\": 0.005, \"type\": \"float\", \"default\": 0.02, \"description\": \"隔离比例\"}, \"unlearning_epochs\": {\"max\": 20, \"min\": 1, \"type\": \"int\", \"default\": 5, \"description\": \"反学习轮数\"}, \"gradient_ascent_step\": {\"max\": 0.5, \"min\": 0.01, \"type\": \"float\", \"default\": 0.1, \"description\": \"梯度上升步长\"}}', 'test', 'test', '2025-07-28 10:30:00', '2025-07-28 10:30:00');
INSERT INTO `sys_algorithm` VALUES (5, '模型蒸馏净化', '通过知识蒸馏技术净化被感染的模型', b'1', 'model_purification', 'post', 'deep_learning', '/algorithms/distillation_purify.py', '{\"fine_tuning_lr\": 0.001, \"recovery_epochs\": 20, \"initial_pruning_ratio\": 0.3, \"use_magnitude_pruning\": true}', '{\"fine_tuning_lr\": {\"max\": 0.01, \"min\": 0.0001, \"type\": \"float\", \"default\": 0.001, \"required\": true, \"description\": \"微调学习率\"}, \"recovery_epochs\": {\"max\": 100, \"min\": 5, \"type\": \"int\", \"default\": 20, \"required\": true, \"description\": \"恢复训练轮数\"}, \"initial_pruning_ratio\": {\"max\": 0.9, \"min\": 0.1, \"type\": \"float\", \"default\": 0.3, \"required\": true, \"description\": \"初始修剪比例\"}, \"use_magnitude_pruning\": {\"type\": \"boolean\", \"default\": true, \"required\": true, \"description\": \"使用幅度修剪\"}}', 'admin', 'admin', '2025-07-28 11:00:00', '2025-07-28 11:00:00');
INSERT INTO `sys_algorithm` VALUES (6, '321', '', b'1', 'data_cleaning', 'pre', 'statistical', '', '{}', '{}', 'admin', 'admin', '2025-08-11 01:55:05', '2025-08-11 01:55:05');

