-- ----------------------------
DROP TABLE IF EXISTS `sys_dataset`;
CREATE TABLE `sys_dataset`  (
  `dataset_id` bigint NOT NULL AUTO_INCREMENT COMMENT '数据集ID',
  `dataset_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '数据集名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '数据集描述',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否启用',
  `dataset_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '数据集类型(image,text,tabular等)',
  `file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文件存储路径',
  `file_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原始文件名',
  `file_size` bigint NULL DEFAULT NULL COMMENT '文件大小(字节)',
  `sample_count` int NULL DEFAULT NULL COMMENT '样本数量',
  `feature_count` int NULL DEFAULT NULL COMMENT '特征数量',
  `class_count` int NULL DEFAULT NULL COMMENT '类别数量',
  `parse_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'pending' COMMENT '解析状态: pending-等待解析, parsing-解析中, success-解析成功, failed-解析失败',
  `parse_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '解析结果消息',
  `parse_time` datetime NULL DEFAULT NULL COMMENT '解析完成时间',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`dataset_id`) USING BTREE,
  UNIQUE INDEX `uniq_dataset_name`(`dataset_name` ASC) USING BTREE,
  INDEX `idx_dataset_type`(`dataset_type` ASC) USING BTREE,
  INDEX `idx_enabled`(`enabled` ASC) USING BTREE,
  INDEX `idx_parse_status`(`parse_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '数据集表' ROW_FORMAT = COMPACT;

