INSERT INTO `sys_dataset` VALUES (1, 'CIFAR-10训练集', 'CIFAR-10图像分类数据集，包含10个类别的60000张32x32彩色图像', b'1', 'image', '/uploads/datasets/cifar10_train.zip', 'cifar10_train.zip', 162345000, 50000, 3072, 10, 'success', '解析成功，发现50000个样本', '2025-07-28 10:30:00', 'admin', 'admin', '2025-07-28 10:00:00', '2025-07-28 10:30:00');
INSERT INTO `sys_dataset` VALUES (2, 'MNIST手写数字集', 'MNIST手写数字识别数据集，包含0-9数字的70000张28x28灰度图像', b'1', 'image', '/uploads/datasets/mnist.zip', 'mnist.zip', 52340000, 70000, 784, 10, 'success', '解析成功，发现70000个样本', '2025-07-28 11:15:00', 'admin', 'admin', '2025-07-28 11:00:00', '2025-07-28 11:15:00');
INSERT INTO `sys_dataset` VALUES (3, '文本情感分析数据', 'IMDb电影评论情感分析数据集，包含正面和负面评论', b'1', 'text', '/uploads/datasets/imdb_reviews.csv', 'imdb_reviews.csv', 84256000, 50000, 1, 2, 'success', '解析成功，发现50000条文本样本', '2025-07-28 12:20:00', 'test', 'test', '2025-07-28 12:00:00', '2025-07-28 12:20:00');
INSERT INTO `sys_dataset` VALUES (4, '中毒CIFAR数据集', '包含后门样本的CIFAR-10数据集，用于测试防御算法', b'1', 'image', '/uploads/datasets/poisoned_cifar10.zip', 'poisoned_cifar10.zip', 165890000, 52000, 3072, 10, 'success', '解析成功，检测到可能的后门样本', '2025-07-28 13:45:00', 'admin', 'admin', '2025-07-28 13:30:00', '2025-07-28 13:45:00');
INSERT INTO `sys_dataset` VALUES (5, '金融欺诈检测数据', '信用卡交易数据，用于欺诈检测模型训练', b'1', 'tabular', '/uploads/datasets/credit_fraud.csv', 'credit_fraud.csv', 143520000, 284807, 30, 2, 'parsing', '正在解析数据结构...', NULL, 'test', 'test', '2025-07-28 14:00:00', '2025-07-28 14:00:00');

