-- ----------------------------
-- Table structure for sys_during_defense
-- ----------------------------
DROP TABLE IF EXISTS `sys_during_defense`;
CREATE TABLE `sys_during_defense`  (
  `task_id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务ID',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '任务描述',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT '任务状态: pending-等待中, running-运行中, success-成功, failed-失败',
  `dataset_id` bigint NOT NULL COMMENT '训练数据集ID',
  `input_model_id` bigint NOT NULL COMMENT '输入模型ID',
  `algorithm_id` bigint NOT NULL COMMENT '防御算法ID',
  `hyper_id` bigint NULL DEFAULT NULL COMMENT '超参数模板ID',
  `custom_params` json NULL COMMENT '自定义参数配置(JSON格式)',
  `start_time` datetime NULL DEFAULT NULL COMMENT '训练开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '训练结束时间',
  `progress` int NULL DEFAULT 0 COMMENT '训练进度百分比',
  `output_model_id` bigint NULL DEFAULT NULL COMMENT '输出模型ID',
  `training_log` json NULL COMMENT '训练日志(JSON格式)',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`task_id`) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_dataset_id`(`dataset_id` ASC) USING BTREE,
  INDEX `idx_input_model_id`(`input_model_id` ASC) USING BTREE,
  INDEX `idx_algorithm_id`(`algorithm_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `fk_during_defense_hyper`(`hyper_id` ASC) USING BTREE,
  INDEX `fk_during_defense_output_model`(`output_model_id` ASC) USING BTREE,
  CONSTRAINT `fk_during_defense_algorithm` FOREIGN KEY (`algorithm_id`) REFERENCES `sys_algorithm` (`algorithm_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_during_defense_dataset` FOREIGN KEY (`dataset_id`) REFERENCES `sys_dataset` (`dataset_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_during_defense_hyper` FOREIGN KEY (`hyper_id`) REFERENCES `sys_hyper` (`template_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_during_defense_input_model` FOREIGN KEY (`input_model_id`) REFERENCES `sys_model` (`model_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_during_defense_output_model` FOREIGN KEY (`output_model_id`) REFERENCES `sys_model` (`model_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '训练中防御任务表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of sys_during_defense
-- ----------------------------
INSERT INTO `sys_during_defense` VALUES (1, 'CIFAR-10 STRIP防御训练', '使用STRIP算法对ResNet-18进行CIFAR-10防御训练，检测并防御后门攻击', 'success', 1, 1, 2, 3, '{\"batch_size\": 32, \"max_epochs\": 50, \"learning_rate\": 0.001, \"perturbation_ratio\": 0.12, \"detection_threshold\": 0.45}', '2025-07-28 18:00:00', '2025-07-28 20:30:00', 100, 9, '{\"epochs\": 50, \"final_loss\": 0.245, \"loss_history\": [2.301, 1.845, 1.234, 0.892, 0.654, 0.432, 0.321, 0.287, 0.265, 0.245], \"best_accuracy\": 0.895, \"detection_rate\": 0.86, \"final_accuracy\": 0.892, \"accuracy_history\": [0.123, 0.234, 0.456, 0.678, 0.789, 0.832, 0.854, 0.871, 0.889, 0.892], \"defense_triggered\": 12}', 'admin', 'admin', '2025-07-28 17:45:00', '2025-07-28 20:30:00');
INSERT INTO `sys_during_defense` VALUES (2, 'ABL防御训练任务', '使用ABL算法对VGG-16进行中毒数据集防御性训练，隔离并反学习后门样本', 'success', 4, 2, 4, 6, '{\"batch_size\": 16, \"learning_rate\": 0.01, \"isolation_ratio\": 0.015, \"unlearning_epochs\": 4, \"gradient_ascent_step\": 0.15}', '2025-07-28 21:00:00', '2025-07-28 23:20:00', 100, 8, '{\"epochs\": 30, \"final_loss\": 0.312, \"loss_history\": [1.987, 1.456, 1.123, 0.898, 0.672, 0.534, 0.421, 0.367, 0.334, 0.312], \"best_accuracy\": 0.881, \"final_accuracy\": 0.876, \"isolation_loss\": 0.45, \"unlearning_loss\": 0.234, \"accuracy_history\": [0.234, 0.456, 0.623, 0.734, 0.812, 0.843, 0.861, 0.869, 0.874, 0.876], \"isolated_samples\": 780}', 'test', 'test', '2025-07-28 20:50:00', '2025-07-28 23:20:00');
INSERT INTO `sys_during_defense` VALUES (3, 'MNIST STRIP防御训练', '对MobileNet-V2在MNIST数据集上进行STRIP防御训练，轻量级后门检测', 'running', 2, 3, 2, 3, '{\"batch_size\": 64, \"max_epochs\": 40, \"learning_rate\": 0.0005, \"perturbation_ratio\": 0.08, \"detection_threshold\": 0.6}', '2025-07-29 09:00:00', NULL, 75, NULL, '{\"current_loss\": 0.187, \"loss_history\": [1.234, 0.987, 0.756, 0.534, 0.423, 0.345, 0.287, 0.234, 0.198, 0.187], \"best_accuracy\": 0.948, \"current_epoch\": 30, \"detection_count\": 23, \"accuracy_history\": [0.567, 0.723, 0.834, 0.876, 0.903, 0.921, 0.934, 0.941, 0.944, 0.945], \"current_accuracy\": 0.945}', 'admin', 'admin', '2025-07-29 08:45:00', '2025-07-29 09:00:00');
INSERT INTO `sys_during_defense` VALUES (4, '文本防御训练任务', '对BERT-Base在文本分类数据上进行ABL防御训练，防御文本后门攻击', 'pending', 3, 4, 4, 6, '{\"batch_size\": 16, \"max_epochs\": 3, \"learning_rate\": 0.00002, \"isolation_ratio\": 0.02, \"unlearning_epochs\": 6, \"gradient_ascent_step\": 0.1}', NULL, NULL, 0, NULL, NULL, 'test', 'test', '2025-07-29 10:00:00', '2025-07-29 10:00:00');
INSERT INTO `sys_during_defense` VALUES (5, '高精度STRIP训练', '使用高精度配置对ResNet-18进行STRIP防御训练，提升检测准确率', 'failed', 1, 1, 2, 3, '{\"batch_size\": 128, \"max_epochs\": 60, \"learning_rate\": 0.001, \"perturbation_ratio\": 0.03, \"detection_threshold\": 0.25}', '2025-07-29 11:00:00', '2025-07-29 11:30:00', 15, NULL, '{\"last_loss\": 1.876, \"error_type\": \"CUDA_OUT_OF_MEMORY\", \"error_message\": \"GPU memory insufficient\", \"last_accuracy\": 0.234, \"completed_epochs\": 3}', 'admin', 'admin', '2025-07-29 10:50:00', '2025-07-29 11:30:00');
INSERT INTO `sys_during_defense` VALUES (6, 'YOLO后门防御训练', '对YOLO-v5s进行目标检测后门防御训练，检测恶意触发器', 'pending', 1, 8, 2, 3, '{\"batch_size\": 16, \"max_epochs\": 100, \"learning_rate\": 0.01, \"perturbation_ratio\": 0.1, \"detection_threshold\": 0.5}', NULL, NULL, 0, NULL, NULL, 'admin', 'admin', '2025-07-29 14:00:00', '2025-07-29 14:00:00');
INSERT INTO `sys_during_defense` VALUES (7, 'U-Net医学图像防御', '对U-Net进行医学图像分割任务的防御训练，确保模型安全性', 'pending', 1, 9, 4, 6, '{\"batch_size\": 8, \"max_epochs\": 50, \"learning_rate\": 0.0001, \"isolation_ratio\": 0.01, \"unlearning_epochs\": 5, \"gradient_ascent_step\": 0.2}', NULL, NULL, 0, NULL, NULL, 'admin', 'admin', '2025-07-29 15:30:00', '2025-07-29 15:30:00');

-- ----------------------------
-- Table structure for sys_hyper
-- ----------------------------
DROP TABLE IF EXISTS `sys_hyper`;
CREATE TABLE `sys_hyper`  (
  `template_id` bigint NOT NULL AUTO_INCREMENT COMMENT '模板ID',
  `template_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '模板描述',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否启用',
  `algorithm_id` bigint NOT NULL COMMENT '关联算法ID',
  `parameter_config` json NULL COMMENT '参数配置(JSON格式)',
  `parameter_schema` json NULL COMMENT '参数模式定义(JSON格式)',
  `is_default` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否为默认模板',
  `applicable_datasets` json NULL COMMENT '适用数据集类型(JSON数组)',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`template_id`) USING BTREE,
  INDEX `idx_algorithm_id`(`algorithm_id` ASC) USING BTREE,
  INDEX `idx_enabled`(`enabled` ASC) USING BTREE,
  INDEX `idx_is_default`(`is_default` ASC) USING BTREE,
  CONSTRAINT `fk_template_algorithm` FOREIGN KEY (`algorithm_id`) REFERENCES `sys_algorithm` (`algorithm_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '超参数模板表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of sys_hyper
-- ----------------------------
INSERT INTO `sys_hyper` VALUES (1, '统计异常检测 - 推荐配置', '推荐参数配置', b'1', 1, '{\"method\": \"zscore\", \"threshold\": 2.0, \"contamination\": 0.1}', '{\"method\": {\"type\": \"select\", \"default\": \"zscore\", \"options\": [\"zscore\", \"iqr\", \"isolation\"], \"description\": \"检测方法\"}, \"threshold\": {\"max\": 5.0, \"min\": 1.0, \"type\": \"float\", \"default\": 2.0, \"description\": \"阈值\"}, \"contamination\": {\"max\": 0.5, \"min\": 0.01, \"type\": \"float\", \"default\": 0.1, \"description\": \"污染比例\"}}', b'1', '[\"image\", \"tabular\"]', 'admin', 'admin', '2025-07-28 09:15:00', '2025-08-04 00:06:43');
INSERT INTO `sys_hyper` VALUES (3, 'STRIP后门检测 - 推荐配置', '推荐参数配置', b'1', 2, '{\"batch_size\": 32, \"perturbation_ratio\": 0.1, \"detection_threshold\": 0.5}', '{\"batch_size\": {\"max\": 128, \"min\": 16, \"type\": \"int\", \"default\": 32, \"description\": \"批次大小\"}, \"perturbation_ratio\": {\"max\": 0.5, \"min\": 0.01, \"type\": \"float\", \"default\": 0.1, \"description\": \"扰动比例\"}, \"detection_threshold\": {\"max\": 0.9, \"min\": 0.1, \"type\": \"float\", \"default\": 0.5, \"description\": \"检测阈值\"}}', b'1', '[\"image\"]', 'admin', 'admin', '2025-07-28 09:45:00', '2025-08-04 00:06:43');
INSERT INTO `sys_hyper` VALUES (5, '神经元修剪 - 推荐配置', '推荐参数配置', b'1', 3, '{\"learning_rate\": 0.0005, \"pruning_ratio\": 0.03, \"fine_tune_epochs\": 15}', '{\"learning_rate\": {\"max\": 0.01, \"min\": 0.0001, \"type\": \"float\", \"default\": 0.001, \"description\": \"学习率\"}, \"pruning_ratio\": {\"max\": 0.2, \"min\": 0.01, \"type\": \"float\", \"default\": 0.05, \"description\": \"修剪比例\"}, \"fine_tune_epochs\": {\"max\": 50, \"min\": 1, \"type\": \"int\", \"default\": 10, \"description\": \"微调轮数\"}}', b'1', '[\"image\", \"text\"]', 'admin', 'admin', '2025-07-28 10:15:00', '2025-08-04 00:13:54');
INSERT INTO `sys_hyper` VALUES (6, 'ABL防御算法 - 推荐配置', '推荐参数配置', b'1', 4, '{\"isolation_ratio\": 0.01, \"unlearning_epochs\": 3, \"gradient_ascent_step\": 0.2}', '{\"isolation_ratio\": {\"max\": 0.1, \"min\": 0.005, \"type\": \"float\", \"default\": 0.02, \"description\": \"隔离比例\"}, \"unlearning_epochs\": {\"max\": 20, \"min\": 1, \"type\": \"int\", \"default\": 5, \"description\": \"反学习轮数\"}, \"gradient_ascent_step\": {\"max\": 0.5, \"min\": 0.01, \"type\": \"float\", \"default\": 0.1, \"description\": \"梯度上升步长\"}}', b'1', '[\"image\", \"text\", \"tabular\"]', 'test', 'admin', '2025-07-28 10:45:00', '2025-08-04 00:13:54');
INSERT INTO `sys_hyper` VALUES (7, '模型蒸馏净化 - 推荐配置', '推荐参数配置', b'1', 5, '{\"alpha\": 0.7, \"temperature\": 4.0, \"distill_epochs\": 20}', '{\"fine_tuning_lr\": {\"max\": 0.01, \"min\": 0.0001, \"type\": \"float\", \"default\": 0.001, \"description\": \"微调学习率\"}, \"recovery_epochs\": {\"max\": 100, \"min\": 5, \"type\": \"int\", \"default\": 20, \"description\": \"恢复训练轮数\"}, \"initial_pruning_ratio\": {\"max\": 0.9, \"min\": 0.1, \"type\": \"float\", \"default\": 0.3, \"description\": \"初始修剪比例\"}, \"use_magnitude_pruning\": {\"type\": \"boolean\", \"default\": true, \"description\": \"使用幅度修剪\"}}', b'1', '[\"image\", \"text\"]', 'admin', 'admin', '2025-08-04 00:08:29', '2025-08-04 00:08:29');

-- ----------------------------
-- Table structure for sys_hyper_backup
-- ----------------------------
DROP TABLE IF EXISTS `sys_hyper_backup`;
CREATE TABLE `sys_hyper_backup`  (
  `template_id` bigint NOT NULL DEFAULT 0 COMMENT '模板ID',
  `template_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '模板描述',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否启用',
  `algorithm_id` bigint NOT NULL COMMENT '关联算法ID',
  `parameter_config` json NULL COMMENT '参数配置(JSON格式)',
  `parameter_schema` json NULL COMMENT '参数模式定义(JSON格式)',
  `is_default` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否为默认模板',
  `applicable_datasets` json NULL COMMENT '适用数据集类型(JSON数组)',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_hyper_backup
