INSERT INTO `sys_hyper_backup` VALUES (1, '统计检测-默认配置', '统计异常检测算法的默认参数配置', b'1', 1, '{\"method\": \"zscore\", \"threshold\": 2.0, \"contamination\": 0.1}', '{\"method\": {\"type\": \"select\", \"options\": [\"zscore\", \"iqr\", \"isolation\"]}, \"threshold\": {\"max\": 5.0, \"min\": 1.0, \"type\": \"float\"}, \"contamination\": {\"max\": 0.5, \"min\": 0.01, \"type\": \"float\"}}', b'1', '[\"image\", \"tabular\"]', 'admin', 'admin', '2025-07-28 09:15:00', '2025-07-28 09:15:00');
INSERT INTO `sys_hyper_backup` VALUES (2, '统计检测-严格模式', '更严格的异常检测参数配置', b'1', 1, '{\"method\": \"isolation\", \"threshold\": 1.5, \"contamination\": 0.05}', '{\"method\": {\"type\": \"select\", \"options\": [\"zscore\", \"iqr\", \"isolation\"]}, \"threshold\": {\"max\": 5.0, \"min\": 1.0, \"type\": \"float\"}, \"contamination\": {\"max\": 0.5, \"min\": 0.01, \"type\": \"float\"}}', b'0', '[\"image\"]', 'admin', 'admin', '2025-07-28 09:20:00', '2025-07-28 09:20:00');
INSERT INTO `sys_hyper_backup` VALUES (3, 'STRIP检测-标准配置', 'STRIP后门检测的标准参数配置', b'1', 2, '{\"batch_size\": 32, \"perturbation_ratio\": 0.1, \"detection_threshold\": 0.5}', '{\"batch_size\": {\"max\": 128, \"min\": 16, \"type\": \"int\"}, \"perturbation_ratio\": {\"max\": 0.5, \"min\": 0.01, \"type\": \"float\"}, \"detection_threshold\": {\"max\": 0.9, \"min\": 0.1, \"type\": \"float\"}}', b'1', '[\"image\"]', 'admin', 'admin', '2025-07-28 09:45:00', '2025-07-28 09:45:00');
INSERT INTO `sys_hyper_backup` VALUES (4, 'STRIP检测-高精度配置', 'STRIP后门检测的高精度参数配置', b'1', 2, '{\"batch_size\": 64, \"perturbation_ratio\": 0.05, \"detection_threshold\": 0.3}', '{\"batch_size\": {\"max\": 128, \"min\": 16, \"type\": \"int\"}, \"perturbation_ratio\": {\"max\": 0.5, \"min\": 0.01, \"type\": \"float\"}, \"detection_threshold\": {\"max\": 0.9, \"min\": 0.1, \"type\": \"float\"}}', b'0', '[\"image\"]', 'test', 'test', '2025-07-28 09:50:00', '2025-07-28 09:50:00');
INSERT INTO `sys_hyper_backup` VALUES (5, '神经元修剪-轻度配置', '轻度的神经元修剪参数，保持模型性能', b'1', 3, '{\"learning_rate\": 0.0005, \"pruning_ratio\": 0.03, \"fine_tune_epochs\": 15}', '{\"learning_rate\": {\"max\": 0.01, \"min\": 0.0001, \"type\": \"float\"}, \"pruning_ratio\": {\"max\": 0.2, \"min\": 0.01, \"type\": \"float\"}, \"fine_tune_epochs\": {\"max\": 50, \"min\": 1, \"type\": \"int\"}}', b'0', '[\"image\", \"text\"]', 'admin', 'admin', '2025-07-28 10:15:00', '2025-07-28 10:15:00');
INSERT INTO `sys_hyper_backup` VALUES (6, 'ABL防御-快速配置', 'ABL算法的快速检测配置', b'1', 4, '{\"isolation_ratio\": 0.01, \"unlearning_epochs\": 3, \"gradient_ascent_step\": 0.2}', '{\"isolation_ratio\": {\"max\": 0.1, \"min\": 0.005, \"type\": \"float\"}, \"unlearning_epochs\": {\"max\": 20, \"min\": 1, \"type\": \"int\"}, \"gradient_ascent_step\": {\"max\": 0.5, \"min\": 0.01, \"type\": \"float\"}}', b'0', '[\"image\", \"text\", \"tabular\"]', 'test', 'test', '2025-07-28 10:45:00', '2025-07-28 10:45:00');

-- ----------------------------
-- Table structure for sys_job
-- ----------------------------
DROP TABLE IF EXISTS `sys_job`;
CREATE TABLE `sys_job`  (
  `job_id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '岗位名称',
  `enabled` bit(1) NOT NULL COMMENT '岗位状态',
  `job_sort` int NULL DEFAULT NULL COMMENT '排序',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`job_id`) USING BTREE,
  UNIQUE INDEX `uniq_name`(`name` ASC) USING BTREE,
  INDEX `idx_enabled`(`enabled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '岗位' ROW_FORMAT = COMPACT;

