-- ----------------------------
-- Table structure for sys_model
-- ----------------------------
DROP TABLE IF EXISTS `sys_model`;
CREATE TABLE `sys_model`  (
  `model_id` bigint NOT NULL AUTO_INCREMENT COMMENT '模型ID',
  `model_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '模型描述',
  `model_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型来源: builtin-内置模型, custom-用户自定义',
  `model_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型类型(cnn,rnn,transformer,linear等)',
  `model_category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模型类别(image_classification,text_classification,regression等)',
  `architecture` json NULL COMMENT '模型架构定义',
  `input_shape` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '输入形状',
  `output_shape` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '输出形状',
  `parameters_count` bigint NULL DEFAULT NULL COMMENT '参数数量',
  `python_file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Python文件路径（仅自定义模型）',
  `python_file_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Python文件原名（仅自定义模型）',
  `python_file_size` bigint NULL DEFAULT NULL COMMENT 'Python文件大小（仅自定义模型）',
  `model_file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模型文件路径',
  `model_config` json NULL COMMENT '模型配置信息',
  `parse_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'pending' COMMENT '解析状态: pending-等待解析, parsing-解析中, success-解析成功, failed-解析失败',
  `parse_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '解析结果消息',
  `parse_time` datetime NULL DEFAULT NULL COMMENT '解析完成时间',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'draft' COMMENT '模型状态: draft-草稿, available-可用, maintenance-维护中, deprecated-已弃用',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`model_id`) USING BTREE,
  INDEX `idx_model_source`(`model_source` ASC) USING BTREE,
  INDEX `idx_model_type`(`model_type` ASC) USING BTREE,
  INDEX `idx_parse_status`(`parse_status` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '模型表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_model
-- ----------------------------
INSERT INTO `sys_model` VALUES (1, 'ResNet-18', 'ResNet 18层深度残差网络，广泛应用于图像分类任务，在ImageNet数据集上表现优异', 'builtin', 'cnn', 'image_classification', '{\"layers\": [\"conv2d\", \"batch_norm\", \"relu\", \"maxpool\", \"residual_blocks\"], \"channels\": [64, 128, 256, 512], \"framework\": \"pytorch\", \"num_blocks\": [2, 2, 2, 2], \"shortcut_type\": \"identity\"}', '224,224,3', '1000', 11689512, NULL, NULL, NULL, '/models/builtin/resnet18.pth', '{\"epochs\": 100, \"optimizer\": \"adam\", \"batch_size\": 32, \"learning_rate\": 0.001, \"loss_function\": \"cross_entropy\"}', 'success', NULL, NULL, 'available', '2025-07-27 16:28:41', '2025-07-30 17:13:31', 0, 'admin', NULL);
INSERT INTO `sys_model` VALUES (2, 'VGG-16', 'VGG 16层卷积神经网络，经典的深度卷积网络架构，结构简单但效果显著', 'builtin', 'cnn', 'image_classification', '{\"layers\": [\"conv2d\", \"relu\", \"maxpool\", \"fully_connected\"], \"channels\": [64, 128, 256, 512, 512], \"fc_layers\": [4096, 4096, 1000], \"framework\": \"pytorch\", \"conv_groups\": [2, 2, 3, 3, 3]}', '224,224,3', '1000', 138357544, NULL, NULL, NULL, '/models/builtin/vgg16.pth', '{\"epochs\": 150, \"momentum\": 0.9, \"optimizer\": \"sgd\", \"batch_size\": 16, \"learning_rate\": 0.01, \"loss_function\": \"cross_entropy\"}', 'success', NULL, NULL, 'available', '2025-07-27 16:28:41', '2025-07-30 17:13:34', 0, 'admin', NULL);
INSERT INTO `sys_model` VALUES (3, 'MobileNet-V2', '轻量级移动端卷积神经网络，专为资源受限环境设计，平衡了精度和效率', 'builtin', 'cnn', 'image_classification', '{\"layers\": [\"conv2d\", \"depthwise_separable_conv\", \"inverted_residual\"], \"framework\": \"pytorch\", \"expansion_factor\": 6, \"width_multiplier\": 1.0, \"resolution_multiplier\": 1.0}', '224,224,3', '1000', 3504872, NULL, NULL, NULL, '/models/builtin/mobilenetv2.pth', '{\"decay\": 0.9, \"epochs\": 300, \"optimizer\": \"rmsprop\", \"batch_size\": 96, \"learning_rate\": 0.045, \"loss_function\": \"cross_entropy\"}', 'success', NULL, NULL, 'available', '2025-07-27 16:28:41', '2025-07-30 17:13:38', 0, 'admin', NULL);
INSERT INTO `sys_model` VALUES (4, 'BERT-Base', 'BERT基础版本，基于Transformer架构的预训练语言模型，适用于各种NLP任务', 'builtin', 'transformer', 'text_classification', '{\"layers\": [\"embedding\", \"transformer_encoder\"], \"framework\": \"pytorch\", \"num_layers\": 12, \"hidden_size\": 768, \"intermediate_size\": 3072, \"num_attention_heads\": 12, \"max_position_embeddings\": 512}', '512', '2', 110104890, NULL, NULL, NULL, '/models/builtin/bert_base.pth', '{\"epochs\": 3, \"optimizer\": \"adamw\", \"batch_size\": 16, \"weight_decay\": 0.01, \"learning_rate\": 0.00002, \"loss_function\": \"cross_entropy\"}', 'success', NULL, NULL, 'available', '2025-07-27 16:28:41', '2025-07-30 17:13:42', 0, 'admin', NULL);
INSERT INTO `sys_model` VALUES (6, 'Linear-Regression', '经典线性回归模型，用于连续值预测任务，简单高效，易于理解和解释', 'builtin', 'linear', 'regression', '{\"layers\": [\"linear\"], \"framework\": \"sklearn\", \"normalize\": false, \"fit_intercept\": true, \"regularization\": \"none\"}', 'variable', '1', 0, NULL, NULL, NULL, '/models/builtin/linear_regression.pkl', '{\"tol\": 0.0001, \"alpha\": 1.0, \"solver\": \"auto\", \"max_iter\": 1000}', 'success', NULL, NULL, 'available', '2025-07-27 16:28:41', '2025-07-30 17:13:45', 0, 'admin', NULL);
INSERT INTO `sys_model` VALUES (7, 'Random-Forest', '随机森林集成学习算法，结合多个决策树的预测结果，适用于分类和回归任务', 'builtin', 'ensemble', 'classification', '{\"bootstrap\": true, \"framework\": \"sklearn\", \"max_depth\": null, \"n_estimators\": 100, \"base_estimator\": \"decision_tree\", \"min_samples_leaf\": 1, \"min_samples_split\": 2}', 'variable', 'variable', 0, NULL, NULL, NULL, '/models/builtin/random_forest.pkl', '{\"n_jobs\": -1, \"criterion\": \"gini\", \"max_features\": \"auto\", \"random_state\": 42}', 'success', NULL, NULL, 'available', '2025-07-27 16:28:41', '2025-07-30 17:13:48', 0, 'admin', NULL);
INSERT INTO `sys_model` VALUES (8, 'YOLO-v5s', 'YOLO v5小型版本，实时目标检测模型，在速度和精度之间取得良好平衡', 'builtin', 'cnn', 'object_detection', '{\"head\": \"YOLOv5Head\", \"neck\": \"PANet\", \"backbone\": \"CSPDarknet\", \"framework\": \"pytorch\", \"num_classes\": 80, \"anchor_based\": true}', '640,640,3', '25200,85', 7235389, NULL, NULL, NULL, '/models/builtin/yolov5s.pt', '{\"epochs\": 300, \"momentum\": 0.937, \"optimizer\": \"sgd\", \"batch_size\": 16, \"weight_decay\": 0.0005, \"learning_rate\": 0.01, \"loss_function\": \"yolo_loss\"}', 'success', NULL, NULL, 'available', '2025-07-27 16:28:41', '2025-07-30 17:13:50', 0, 'admin', NULL);
INSERT INTO `sys_model` VALUES (9, 'U-Net', 'U-Net卷积神经网络，专为生物医学图像分割设计，采用编码器-解码器架构', 'builtin', 'cnn', 'image_segmentation', '{\"layers\": [\"conv2d\", \"batch_norm\", \"relu\", \"maxpool\", \"upconv\", \"skip_connections\"], \"decoder\": \"UNet\", \"encoder\": \"ResNet34\", \"framework\": \"pytorch\"}', '512,512,3', '512,512,1', 24445770, NULL, NULL, NULL, '/models/builtin/unet.pth', '{\"epochs\": 100, \"optimizer\": \"adam\", \"batch_size\": 8, \"learning_rate\": 0.0001, \"loss_function\": \"dice_loss\"}', 'success', NULL, NULL, 'available', '2025-07-27 16:28:41', '2025-07-28 19:21:33', 0, '1', '1');
INSERT INTO `sys_model` VALUES (10, 'ResNet-18-STRIP-Defense', 'ResNet-18经过STRIP防御训练后的模型，具备后门检测和防御能力', 'custom', 'cnn', 'image_classification', '{\"layers\": [\"conv2d\", \"batch_norm\", \"relu\", \"maxpool\", \"residual_blocks\"], \"channels\": [64, 128, 256, 512], \"framework\": \"pytorch\", \"num_blocks\": [2, 2, 2, 2], \"defense_type\": \"STRIP\", \"shortcut_type\": \"identity\"}', '224,224,3', '1000', 11689512, NULL, NULL, NULL, '/models/defense/resnet18_strip_defended.pth', '{\"epochs\": 50, \"optimizer\": \"adam\", \"batch_size\": 32, \"learning_rate\": 0.001, \"loss_function\": \"cross_entropy\", \"defense_algorithm\": \"STRIP\", \"original_model_id\": 1, \"detection_threshold\": 0.45}', 'success', '经过STRIP防御训练，具备后门检测能力，检测准确率86%', '2025-07-28 20:30:00', 'available', '2025-07-28 20:30:00', '2025-07-28 20:30:00', 0, 'admin', 'admin');
INSERT INTO `sys_model` VALUES (11, 'VGG-16-ABL-Defense', 'VGG-16经过ABL防御训练后的模型，能够抵抗后门攻击', 'custom', 'cnn', 'image_classification', '{\"layers\": [\"conv2d\", \"relu\", \"maxpool\", \"fully_connected\"], \"channels\": [64, 128, 256, 512, 512], \"fc_layers\": [4096, 4096, 1000], \"framework\": \"pytorch\", \"conv_groups\": [2, 2, 3, 3, 3], \"defense_type\": \"ABL\"}', '224,224,3', '1000', 138357544, NULL, NULL, NULL, '/models/defense/vgg16_abl_defended.pth', '{\"epochs\": 30, \"momentum\": 0.9, \"optimizer\": \"sgd\", \"batch_size\": 16, \"learning_rate\": 0.01, \"loss_function\": \"cross_entropy\", \"isolation_ratio\": 0.015, \"defense_algorithm\": \"ABL\", \"original_model_id\": 2}', 'success', '经过ABL防御训练，成功隔离780个可疑样本，模型安全性提升', '2025-07-28 23:20:00', 'available', '2025-07-28 23:20:00', '2025-07-28 23:20:00', 0, 'test', 'test');
INSERT INTO `sys_model` VALUES (12, '321', NULL, 'builtin', 'cnn', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL, 'draft', '2025-08-11 01:54:14', '2025-08-11 01:54:14', 0, 'admin', NULL);

-- ----------------------------
-- Table structure for sys_model_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_model_log`;
CREATE TABLE `sys_model_log`  (
  `log_id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `model_id` bigint NOT NULL COMMENT '模型ID',
  `step_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '解析步骤名称',
  `step_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '步骤状态: running, success, failed',
  `step_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '步骤消息',
  `step_result` json NULL COMMENT '步骤结果数据',
  `start_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `duration` int NULL DEFAULT NULL COMMENT '耗时(秒)',
  PRIMARY KEY (`log_id`) USING BTREE,
  INDEX `idx_model_id`(`model_id` ASC) USING BTREE,
  INDEX `idx_step_name`(`step_name` ASC) USING BTREE,
  CONSTRAINT `sys_model_log_ibfk_1` FOREIGN KEY (`model_id`) REFERENCES `sys_model` (`model_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '模型解析日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_model_log
-- ----------------------------

-- ----------------------------
-- Table structure for sys_post_defense
-- ----------------------------
DROP TABLE IF EXISTS `sys_post_defense`;
CREATE TABLE `sys_post_defense`  (
  `task_id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务ID',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '任务描述',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT '任务状态: pending-等待中, running-运行中, success-成功, failed-失败',
  `input_model_id` bigint NOT NULL COMMENT '输入模型ID（待检测/净化的模型）',
  `test_dataset_id` bigint NULL DEFAULT NULL COMMENT '测试数据集ID（可选，用于性能评估）',
  `algorithm_id` bigint NOT NULL COMMENT '防御算法ID',
  `hyper_id` bigint NULL DEFAULT NULL COMMENT '超参数模板ID',
  `custom_params` json NULL COMMENT '自定义参数配置(JSON格式)',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `progress` int NULL DEFAULT 0 COMMENT '进度百分比',
  `defense_result` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '防御结果: clean-模型清洁, purified-已净化, infected-发现后门, failed-检测失败',
  `output_model_id` bigint NULL DEFAULT NULL COMMENT '输出模型ID（净化后的安全模型）',
  `output_model_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '净化后模型文件路径（兼容性保留）',
  `performance_metrics` json NULL COMMENT '性能指标对比(JSON格式): 原始准确率、净化后准确率、性能损失等',
  `risk_assessment` json NULL COMMENT '风险评估报告(JSON格式): 置信度、风险等级、后门概率、检测详情等',
  `detection_report` json NULL COMMENT '检测报告(JSON格式): 可疑层、触发器模式、检测过程等',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`task_id`) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_input_model_id`(`input_model_id` ASC) USING BTREE,
  INDEX `idx_algorithm_id`(`algorithm_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `fk_post_defense_test_dataset`(`test_dataset_id` ASC) USING BTREE,
  INDEX `fk_post_defense_hyper`(`hyper_id` ASC) USING BTREE,
  INDEX `fk_post_defense_output_model`(`output_model_id` ASC) USING BTREE,
  CONSTRAINT `fk_post_defense_algorithm` FOREIGN KEY (`algorithm_id`) REFERENCES `sys_algorithm` (`algorithm_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_post_defense_hyper` FOREIGN KEY (`hyper_id`) REFERENCES `sys_hyper` (`template_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_post_defense_input_model` FOREIGN KEY (`input_model_id`) REFERENCES `sys_model` (`model_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_post_defense_output_model` FOREIGN KEY (`output_model_id`) REFERENCES `sys_model` (`model_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_post_defense_test_dataset` FOREIGN KEY (`test_dataset_id`) REFERENCES `sys_dataset` (`dataset_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '训练后防御任务表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of sys_post_defense
-- ----------------------------
INSERT INTO `sys_post_defense` VALUES (1, 'ResNet模型后门检测', '检测ResNet-18模型是否包含后门触发器', 'success', 1, 1, 3, NULL, '{\"layer_analysis\": true, \"trigger_search\": true, \"detection_threshold\": 0.8}', '2025-08-08 14:00:00', '2025-08-08 14:25:00', 100, 'clean', NULL, NULL, '{\"test_accuracy\": 0.932, \"inference_time_ms\": 45, \"original_accuracy\": 0.934, \"performance_stable\": true}', '{\"confidence\": 0.96, \"risk_level\": \"very_low\", \"trigger_patterns\": \"none_detected\", \"suspicious_layers\": [], \"backdoor_probability\": 0.04}', '{\"scan_duration\": \"25min\", \"scanned_layers\": 18, \"analyzed_neurons\": 512000, \"detection_method\": \"activation_analysis\"}', 'admin', 'admin', '2025-08-08 13:45:00', '2025-08-08 14:25:00');
INSERT INTO `sys_post_defense` VALUES (2, 'VGG模型净化任务', '使用神经元修剪净化VGG-16中发现的后门', 'success', 2, 2, 3, NULL, '{\"learning_rate\": 0.0008, \"pruning_ratio\": 0.04, \"fine_tune_epochs\": 12}', '2025-08-08 15:30:00', '2025-08-08 16:45:00', 100, 'purified', 10, '/models/purified/vgg16_purified_20250808.pth', '{\"accuracy_drop\": 0.005, \"original_accuracy\": 0.876, \"purified_accuracy\": 0.871, \"backdoor_success_rate_after\": 0.02, \"backdoor_success_rate_before\": 0.95}', '{\"confidence\": 0.92, \"risk_level\": \"low\", \"mitigation_success\": true, \"backdoor_probability\": 0.08}', '{\"trigger_type\": \"patch_trigger\", \"affected_layers\": [12, 13, 14], \"pruning_details\": \"removed_256_neurons\", \"detected_backdoor\": true}', 'admin', 'admin', '2025-08-08 15:15:00', '2025-08-08 16:45:00');
INSERT INTO `sys_post_defense` VALUES (3, 'MobileNet安全评估', '对训练完成的MobileNet模型进行全面安全评估', 'running', 3, NULL, 5, NULL, '{\"adversarial_test\": true, \"multiple_datasets\": true, \"comprehensive_scan\": true}', '2025-08-08 17:00:00', NULL, 65, NULL, NULL, NULL, '{\"tested_samples\": 15000, \"current_accuracy\": 0.88, \"estimated_completion\": \"30min\"}', '{\"preliminary_risk\": \"low\", \"samples_analyzed\": 15000, \"current_confidence\": 0.75}', '{\"total_layers\": 12, \"current_layer\": 8, \"scan_progress\": \"65%\"}', 'test', 'test', '2025-08-08 16:45:00', '2025-08-08 17:00:00');
INSERT INTO `sys_post_defense` VALUES (4, 'BERT模型蒸馏净化', '使用知识蒸馏技术净化BERT文本分类模型中的后门', 'success', 4, 3, 5, 7, '{\"alpha\": 0.6, \"temperature\": 5.0, \"distill_epochs\": 25, \"teacher_model_clean\": true}', '2025-08-08 19:00:00', '2025-08-08 20:30:00', 100, 'purified', 11, '/models/purified/bert_distilled_20250808.pth', '{\"accuracy_drop\": 0.006, \"original_accuracy\": 0.912, \"purified_accuracy\": 0.906, \"inference_time_increase\": \"8%\", \"backdoor_success_rate_after\": 0.05, \"backdoor_success_rate_before\": 0.89}', '{\"confidence\": 0.88, \"risk_level\": \"low\", \"residual_risk\": \"minimal\", \"mitigation_success\": true, \"backdoor_probability\": 0.12}', '{\"trigger_type\": \"text_pattern\", \"detected_backdoor\": true, \"distillation_details\": \"knowledge_transfer_successful\", \"affected_attention_heads\": [3, 7, 11]}', 'test', 'test', '2025-08-08 18:45:00', '2025-08-08 20:30:00');

-- ----------------------------
-- Table structure for sys_pre_defense
-- ----------------------------
DROP TABLE IF EXISTS `sys_pre_defense`;
CREATE TABLE `sys_pre_defense`  (
  `task_id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务ID',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '任务描述',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT '任务状态: pending-等待中, running-运行中, success-成功, failed-失败',
  `dataset_id` bigint NOT NULL COMMENT '输入数据集ID',
  `algorithm_id` bigint NOT NULL COMMENT '清洗算法ID',
  `cleaning_result` json NULL COMMENT '清洗结果(JSON格式): 包含样本统计、损失分布、质量指标等',
  `hyper_id` bigint NULL DEFAULT NULL COMMENT '超参数模板ID',
  `custom_params` json NULL COMMENT '自定义参数(JSON格式)',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `progress` int NULL DEFAULT 0 COMMENT '进度百分比',
  `output_dataset_id` bigint NULL DEFAULT NULL COMMENT '清洗后数据集ID',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `execution_snapshot` json NULL COMMENT '执行参数快照(JSON格式): 每次启动时冻结的资源与参数',
  PRIMARY KEY (`task_id`) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_dataset_id`(`dataset_id` ASC) USING BTREE,
  INDEX `idx_algorithm_id`(`algorithm_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `fk_pre_defense_output_dataset`(`output_dataset_id` ASC) USING BTREE,
  INDEX `fk_pre_defense_hyper`(`hyper_id` ASC) USING BTREE,
  CONSTRAINT `fk_pre_defense_algorithm` FOREIGN KEY (`algorithm_id`) REFERENCES `sys_algorithm` (`algorithm_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_pre_defense_dataset` FOREIGN KEY (`dataset_id`) REFERENCES `sys_dataset` (`dataset_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_pre_defense_hyper` FOREIGN KEY (`hyper_id`) REFERENCES `sys_hyper` (`template_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_pre_defense_output_dataset` FOREIGN KEY (`output_dataset_id`) REFERENCES `sys_dataset` (`dataset_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '训练前防御任务表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of sys_pre_defense
-- ----------------------------
INSERT INTO `sys_pre_defense` VALUES (1, 'CIFAR-10数据清洗任务', '使用统计异常检测清洗CIFAR-10训练集中的异常样本', 'success', 1, 1, '{\"sample_stats\": {\"cleaned_count\": 49200, \"removed_count\": 800, \"original_count\": 50000, \"retention_rate\": 0.984000000}, \"cleaning_details\": {\"quality_metrics\": {\"data_integrity\": 0.97, \"label_consistency\": 0.98}, \"algorithm_config\": {\"method\": \"zscore\", \"threshold\": 2.5, \"contamination\": 0.08}}, \"loss_distribution\": {\"improvement\": {\"mean_reduction\": 0.16, \"variance_reduction\": 0.17}, \"after_cleaning\": {\"std_loss\": 0.72, \"mean_loss\": 2.18, \"percentiles\": {\"p50\": 2.09, \"p95\": 3.85}}, \"before_cleaning\": {\"std_loss\": 0.89, \"mean_loss\": 2.34, \"percentiles\": {\"p50\": 2.21, \"p95\": 4.56}}}}', NULL, '{\"method\": \"zscore\", \"threshold\": 2.5, \"contamination\": 0.08}', '2025-07-28 14:00:00', '2025-07-28 14:35:00', 100, 2, 'admin', 'admin', '2025-07-28 13:45:00', '2025-07-28 14:35:00', NULL);
INSERT INTO `sys_pre_defense` VALUES (2, '中毒数据集清洗任务', '使用严格模式清洗包含后门样本的CIFAR数据集', 'success', 4, 1, '{\"sample_stats\": {\"cleaned_count\": 49500, \"removed_count\": 2500, \"original_count\": 52000, \"retention_rate\": 0.951923076}, \"cleaning_details\": {\"quality_metrics\": {\"data_integrity\": 0.97, \"label_consistency\": 0.98}, \"algorithm_config\": {\"method\": \"isolation\", \"threshold\": 1.8, \"contamination\": 0.12}}, \"loss_distribution\": {\"improvement\": {\"mean_reduction\": 0.16, \"variance_reduction\": 0.17}, \"after_cleaning\": {\"std_loss\": 0.72, \"mean_loss\": 2.18, \"percentiles\": {\"p50\": 2.09, \"p95\": 3.85}}, \"before_cleaning\": {\"std_loss\": 0.89, \"mean_loss\": 2.34, \"percentiles\": {\"p50\": 2.21, \"p95\": 4.56}}}}', NULL, '{\"method\": \"isolation\", \"threshold\": 1.8, \"contamination\": 0.12}', '2025-07-28 15:20:00', '2025-07-28 16:10:00', 100, NULL, 'admin', 'admin', '2025-07-28 15:00:00', '2025-07-28 16:10:00', NULL);
INSERT INTO `sys_pre_defense` VALUES (3, 'MNIST数据预处理', '对MNIST数据集进行标准的异常检测处理', 'running', 2, 1, NULL, NULL, '{\"method\": \"zscore\", \"threshold\": 2.0, \"contamination\": 0.05}', '2025-07-28 16:30:00', NULL, 65, NULL, 'test', 'test', '2025-07-28 16:15:00', '2025-07-28 16:30:00', NULL);
INSERT INTO `sys_pre_defense` VALUES (4, '文本数据清洗任务', '对情感分析数据集进行数据质量检查和清洗', 'running', 3, 1, NULL, NULL, '{\"method\": \"iqr\", \"threshold\": 3.0, \"contamination\": 0.15}', '2025-08-03 03:13:04', NULL, 1, NULL, 'test', 'test', '2025-07-28 17:00:00', '2025-07-28 17:00:00', NULL);

-- ----------------------------
-- Table structure for sys_quartz_job
-- ----------------------------
DROP TABLE IF EXISTS `sys_quartz_job`;
CREATE TABLE `sys_quartz_job`  (
  `job_id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `bean_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Spring Bean名称',
  `cron_expression` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'cron 表达式',
  `is_pause` bit(1) NULL DEFAULT NULL COMMENT '状态：1暂停、0启用',
  `job_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务名称',
  `method_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '方法名称',
  `params` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '参数',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `person_in_charge` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '负责人',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报警邮箱',
  `sub_task` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '子任务ID',
  `pause_after_failure` bit(1) NULL DEFAULT NULL COMMENT '任务失败后是否暂停',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`job_id`) USING BTREE,
  INDEX `idx_is_pause`(`is_pause` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '定时任务' ROW_FORMAT = COMPACT;

